// output, and escape sequences could rewrite the user's terminal.
const FORBIDDEN_TEXT_CHARS = /[\p{Cc}\p{Zl}\p{Zp}]/u;
const ID_PATTERN = /^\d+$/;

/**
 * Trim and validate todo text supplied by the user.
 * @param {unknown} raw
 * @returns {string}
 * @throws {UsageError} when the text is empty, too long, or not a single line.
 */
export function normalizeText(raw) {
  if (typeof raw !== 'string' || raw.trim() === '') {
    throw new UsageError('Todo text cannot be empty. Usage: node index.js add "<text>"');
  }
  const text = raw.trim();
  if (FORBIDDEN_TEXT_CHARS.test(text)) {
    throw new UsageError('Todo text must be a single line without control characters.');
  }
  const length = [...text].length;
  if (length > MAX_TEXT_LENGTH) {
    throw new UsageError(
      `Todo text is ${length} characters long; the maximum is ${MAX_TEXT_LENGTH}.`,
    );
  }
  return text;
}

/**
 * Parse a todo id from a command-line argument.
 * @param {unknown} raw
 * @returns {number}
 * @throws {UsageError} unless raw is a string of digits naming a positive safe integer.
 */
export function parseId(raw) {
  const id = typeof raw === 'string' && ID_PATTERN.test(raw) ? Number(raw) : NaN;
  if (!Number.isSafeInteger(id) || id < 1) {
    throw new UsageError(`Invalid todo id "${raw}". Expected a positive integer such as 1.`);
  }
  return id;
}

/**
 * Id for the next new todo: one more than the highest existing id.
 * @param {readonly Todo[]} todos
 * @returns {number}
 */
export function nextId(todos) {
  return todos.reduce((max, todo) => Math.max(max, todo.id), 0) + 1;
}

/**
 * Return a new list with a pending todo appended. The input list is not modified.
 * @param {readonly Todo[]} todos
 * @param {unknown} text Raw text; validated with {@link normalizeText}.
 * @param {Date} [now]
 * @returns {{ todos: Todo[], todo: Todo }}
 */
export function addTodo(todos, text, now = new Date()) {
  const todo = {
    id: nextId(todos),
    text: normalizeText(text),
    completed: false,
    createdAt: now.toISOString(),
  };
  return { todos: [...todos, todo], todo };
}

/**
 * Return a new list with the given todo marked done. Completing an already
 * completed todo is not an error; the original list is returned unchanged.
 * @param {readonly Todo[]} todos
 * @param {number} id
 * @returns {{ todos: readonly Todo[], todo: Todo, alreadyCompleted: boolean }}
 * @throws {NotFoundError}
 */
export function completeTodo(todos, id) {
  const index = indexOf(todos, id);
  const existing = todos[index];
  if (existing.completed) {
    return { todos, todo: existing, alreadyCompleted: true };
  }
  const todo = { ...existing, completed: true };
  return { todos: todos.with(index, todo), todo, alreadyCompleted: false };
