/**
 * Return a new list without the given todo.
 * @param {readonly Todo[]} todos
 * @param {number} id
 * @returns {{ todos: Todo[], todo: Todo }}
 * @throws {NotFoundError}
 */
export function deleteTodo(todos, id) {
  const index = indexOf(todos, id);
  return { todos: todos.toSpliced(index, 1), todo: todos[index] };
}

/**
 * @param {readonly Todo[]} todos
 * @param {number} id
 * @returns {number}
 */
function indexOf(todos, id) {
  const index = todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new NotFoundError(id);
  }
  return index;
}
/** @typedef {import('./todos.js').Todo} Todo */

/** Printed by `list` when there are no todos. */
export const EMPTY_LIST_MESSAGE = 'No todos yet. Add one with: node index.js add "Buy groceries"';

/**
 * One list line, e.g. `1. [x] Buy groceries`.
 * @param {Todo} todo
 * @returns {string}
 */
export function formatTodo(todo) {
  return `${todo.id}. [${todo.completed ? 'x' : ' '}] ${todo.text}`;
}

/**
 * The full `list` output: one line per todo followed by a pending/done summary.
 * @param {readonly Todo[]} todos
 * @returns {string} Output without a trailing newline.
 */
export function formatTodoList(todos) {
  if (todos.length === 0) {
    return EMPTY_LIST_MESSAGE;
  }
  const done = todos.filter((todo) => todo.completed).length;
  const noun = todos.length === 1 ? 'todo' : 'todos';
  const summary = `${todos.length} ${noun}: ${todos.length - done} pending, ${done} done`;
  return [...todos.map(formatTodo), '', summary].join('\n');
