const FIXED_NOW = () => new Date('2026-09-30T12:34:56.789Z');

describe('run: help and dispatch', () => {
  it('prints usage to stderr and exits 2 with no command', () => {
    const result = runInProcess([], { cwd: '/nonexistent' });
    assert.equal(result.code, EXIT_USAGE);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, `${USAGE}\n`);
  });

  for (const flag of ['help', '--help', '-h']) {
    it(`prints usage to stdout and exits 0 for "${flag}"`, () => {
      const result = runInProcess([flag], { cwd: '/nonexistent' });
      assert.equal(result.code, EXIT_SUCCESS);
      assert.equal(result.stdout, `${USAGE}\n`);
      assert.equal(result.stderr, '');
    });
  }

  for (const command of ['frob', 'ADD', '__proto__', 'toString', 'constructor', '']) {
    it(`rejects unknown command ${JSON.stringify(command)} with usage`, (t) => {
      const dir = tempDir(t);
      const result = runInProcess([command], { cwd: dir });
      assert.equal(result.code, EXIT_USAGE);
      assert.ok(result.stderr.startsWith(`Error: Unknown command "${command}".`));
      assert.ok(result.stderr.includes(USAGE));
      assert.equal(fs.existsSync(todosPath(dir)), false);
    });
  }
});

