  return dir;
}

/** Run `node index.js ...args` as a child process with `cwd` as its working directory. */
export function runCli(args, { cwd }) {
  const result = spawnSync(process.execPath, [INDEX_PATH, ...args], { cwd, encoding: 'utf8', timeout: 10_000 });
  if (result.error) {
    throw result.error;
  }
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

/** Async variant of {@link runCli} so several processes can run at once. */
export function runCliAsync(args, { cwd }) {
  return new Promise((resolve, reject) => {
    const child = spawn(process.execPath, [INDEX_PATH, ...args], { cwd, timeout: 20_000 });
    let stdout = '';
    let stderr = '';
    child.stdout.setEncoding('utf8').on('data', (chunk) => { stdout += chunk; });
    child.stderr.setEncoding('utf8').on('data', (chunk) => { stderr += chunk; });
    child.on('error', reject);
    child.on('close', (code) => resolve({ code, stdout, stderr }));
  });
}

