describe('run: edit', () => {
  const original = [
    makeTodo({ id: 1, text: 'First' }),
    makeTodo({ id: 2, text: 'Second', completed: true, createdAt: '2026-02-02T00:00:00.000Z' }),
  ];
  const EMPTY_TEXT = 'Error: Todo text cannot be empty. Usage: node index.js edit <id> "<text>"\\n';

  it('replaces the text and keeps id, completed and createdAt', (t) => {
    const dir = tempDir(t);
    writeTodos(dir, original);
    const result = runInProcess(['edit', '2', 'Updated text'], { cwd: dir, now: FIXED_NOW });
    assert.equal(result.code, EXIT_SUCCESS);
    assert.equal(result.stdout, 'Edited todo #2: Updated text\\n');
    assert.equal(result.stderr, '');
    assert.deepEqual(readTodos(dir), [original[0], { ...original[1], text: 'Updated text' }]);
  });

  it('joins unquoted words and trims the text', (t) => {
    const dir = tempDir(t);
    writeTodos(dir, original);
    runInProcess(['edit', '1', 'Walk', 'the', 'dog'], { cwd: dir });
    assert.equal(readTodos(dir)[0].text, 'Walk the dog');
    runInProcess(['edit', '1', '  padded  '], { cwd: dir });
    assert.equal(readTodos(dir)[0].text, 'padded');
  });

  it('is reflected by list', (t) => {
    const dir = tempDir(t);
    writeTodos(dir, original);
    runInProcess(['edit', '1', 'Changed'], { cwd: dir });
    assert.match(runInProcess(['list'], { cwd: dir }).stdout, /^1\\. \\[ \\] Changed$/m);
  });

  const failures = [
    ['no arguments', [], 2, 'Error: Missing todo id. Usage: node index.js edit <id> "<text>"\\n'],
    ['a missing text', ['1'], 2, 'Error: Missing todo text. Usage: node index.js edit <id> "<text>"\\n'],
    ['an empty text', ['1', ''], 2, EMPTY_TEXT],
    ['a whitespace-only text', ['1', '   '], 2, EMPTY_TEXT],
    ['an invalid id', ['abc', 'New'], 2, 'Error: Invalid todo id "abc". Expected a positive integer such as 1.\\n'],
    ['a zero id', ['0', 'New'], 2, 'Error: Invalid todo id "0". Expected a positive integer such as 1.\\n'],
    ['text with a control character', ['1', 'a\\u001b[31mb'], 2, 'Error: Todo text must be a single line without control characters.\\n'],
    ['an id that does not exist', ['9', 'New'], 1, 'Error: Todo #9 not found. Run "node index.js list" to see existing ids.\\n'],
  ];
  for (const [name, args, code, stderr] of failures) {
    it(`exits ${code} for ${name} and leaves todos.json unchanged`, (t) => {
      const dir = tempDir(t);
      writeTodos(dir, original);
      const before = fs.readFileSync(todosPath(dir), 'utf8');
      const result = runInProcess(['edit', ...args], { cwd: dir });
      assert.equal(result.code, code);
      assert.equal(result.stdout, '');
      assert.equal(result.stderr, stderr);
      assert.equal(fs.readFileSync(todosPath(dir), 'utf8'), before);
    });
  }

  it('exits 1 without creating todos.json when there are no todos', (t) => {
    const dir = tempDir(t);
    const result = runInProcess(['edit', '1', 'New'], { cwd: dir });
    assert.equal(result.code, EXIT_FAILURE);
    assert.match(result.stderr, /Todo #1 not found/);
    assert.equal(fs.existsSync(todosPath(dir)), false);
  });
});

